<script setup>
import {ref,onMounted,onBeforeUnmount,computed,inject} from 'vue';import {useRoute} from 'vue-router';import {user,staticData} from '@/store';import LinIcon from './LinIcon.vue';import BlogSearch from '@/components/Search/blog-search.vue';import SwitchTheme from '@/components/SwitchTheme/index.vue';
const site=inject('lin-site',ref({}));const me=computed(()=>user().getUserInfo),route=useRoute(),open=ref(false),progress=ref(0);const links=computed(()=>[['/home','随手记','book'],['/moments','说说','chat'],['/albums','相册','image'],['/archives','时光轴','clock'],['/about','关于','spark'],...(me.value.role==='admin'?[['/admin/room','我的空间','grid']]:[])]);
function scroll(){progress.value=Math.max(0,Math.min(100,scrollY/(document.documentElement.scrollHeight-innerHeight||1)*100));}
function key(e){if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();document.querySelector('.lin-search-button')?.click();}}
onMounted(()=>{addEventListener('scroll',scroll,{passive:true});addEventListener('keydown',key);});onBeforeUnmount(()=>{removeEventListener('scroll',scroll);removeEventListener('keydown',key);});
</script>
<template><header class="lin-header"><a class="lin-brand" href="/"><span class="lin-mark">L<span>✦</span></span><span class="brand-title">{{site.title||'Lin 的随手记'}}</span></a><button class="lin-mobile-toggle" aria-label="展开导航" @click="open=!open"><LinIcon name="menu"/></button><nav :class="{open}"><a v-for="[url,label,icon] in links" :key="url" :href="url" :class="{active:route.path===url}" @click="open=false"><LinIcon :name="icon" :size="17"/>{{label}}</a></nav><div class="lin-header-tools"><BlogSearch/><SwitchTheme/><a class="lin-write" :href="me.role==='admin'?'/admin/article/addArticle':me.id?'/admin/account':'/login'"><LinIcon :name="me.role==='admin'?'pen':'user'" :size="17"/><span>{{me.role==='admin'?'写文章':me.id?'我的资料':'登录'}}</span></a></div><span class="lin-progress" :style="{width:progress+'%'}"/></header></template>
